package com.jobpilot.job;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDateTime;public final class JobDtos{private JobDtos(){}public record CreateJob(@NotBlank String title,@NotBlank String company,String location,boolean remote,BigDecimal salaryMin,BigDecimal salaryMax,String description,String url){}public record JobView(Long id,String title,String company,String location,boolean remote,BigDecimal salaryMin,BigDecimal salaryMax,String description,String url,String source,LocalDateTime publishedAt){}public static JobView view(JobOffer j){return new JobView(j.getId(),j.getTitle(),j.getCompany(),j.getLocation(),j.isRemote(),j.getSalaryMin(),j.getSalaryMax(),j.getDescription(),j.getUrl(),j.getSource(),j.getPublishedAt());}}
